# Search for multi-line imports that span from "import" to "from 'shared/types'"
find . -type f \( -name "*.ts" -o -name "*.tsx" -o -name "*.js" -o -name "*.jsx" \) -print0 | \
  while IFS= read -r -d '' file; do
    if awk '
      /^import.*{/ {
        start = NR;
        content = $0;
        next
      }
      start > 0 {
        content = content "\n" $0;
        if (/from.*["'"'"'].*shared\/types["'"'"']/) {
          if (content ~ /Session/) {
            print FILENAME;
          }
          start = 0;
        }
        if (NR - start > 50) {
          start = 0;
        }
      }
    ' "$file"; then
      :
    fi
  done | sort -u

